def get_antibiotic_therapy_priority(patient):
    """
    Compute the antibiotic therapy priority of the patient.
    patient: A patient object with attributes: age, resource_availability, comorbidities, severity, gender, symptoms, duration_of_condition
    """
    score = 0

    # Consider the patient's age: older patients might need higher priority
    if patient.age > 65:
        score += 3
    elif patient.age > 50:
        score += 2
    else:
        score += 1

    # Consider the severity of the condition
    if patient.severity >= 8:
        score += 3
    elif patient.severity >= 6:
        score += 2
    else:
        score += 1

    # Consider the presence of certain symptoms: these might require immediate antibiotic therapy
    if 'septic' in patient.symptoms or 'bloodstream infection' in patient.symptoms:
        score += 3
    elif 'malaise' in patient.symptoms or 'fever' in patient.symptoms:
        score += 2

    # Consider the number of comorbidities: patients with more might need higher priority
    if patient.comorbidities >= 5:
        score += 3
    elif patient.comorbidities >= 3:
        score += 2
    elif patient.comorbidities >= 1:
        score += 1

    # Consider gender: males might need higher priority in certain cases
    if patient.gender == 'male':
        score += 1

    # Consider resource availability
    if patient.resource_availability == 'limited':
        score -= 1

    return score

