import random

def generate_sequence(variables, previous=None):
    if not variables:
        return []

    variable = random.choice(variables)
    while variable == previous:
        variable = random.choice(variables)

    return [variable] + generate_sequence(list(filter(lambda x: x != variable, variables)), previous=variable)

