def neurological_priority(patient):
    """
    Compute the neurological therapy priority of patients.
    patient: A patient object with attributes: age, resource_availability, comorbidities, severity, gender, symptoms, duration_of_condition
    """

    patient_score = 0

    # Severe neurological symptoms or conditions
    severe_symptoms = ['seizure', 'paralysis', 'dizziness', 'vision loss', 'numbness', 'tremor']
    if any(symptom in patient.symptoms for symptom in severe_symptoms) or patient.severity >= 7:
        patient_score += 5
    elif any(symptom in patient.symptoms for symptom in severe_symptoms) or patient.severity >= 4:
        patient_score += 4
    elif patient.severity >= 2:
        patient_score += 3

    # Stroke-like symptoms or severe conditions
    stroke_symptoms = ['double vision', 'numbness/tingling', 'arm weakness', 'speech difficulties', 'headache', 'impaired balance']
    if any(symptom in patient.symptoms for symptom in stroke_symptoms) or patient.severity >= 7:
        patient_score += 5
    elif any(symptom in patient.symptoms for symptom in stroke_symptoms) or patient.severity >= 4:
        patient_score += 4

    # Chronic neurological conditions
    if patient.duration_of_condition > 12:
        patient_score += 3
    elif patient.duration_of_condition > 6:
        patient_score += 2

    # Age-related comorbidity scoring
    if patient.comorbidities >= 3:
        patient_score += 3
    elif patient.comorbidities >= 1:
        patient_score += 2
    else:
        patient_score += 1

    # Female gender may warrant increased priority in specific clinical contexts.
    if patient.gender == 'female':
        patient_score += 2

    # Reduce the score based on resource availability
    if not patient.resource_availability:
        patient_score -= 3

    return patient_score

def factorial(n):
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

